export const OUTSKIRTS_DISTRICTS: OutskirtsDistrict[] = [
  { id: "gate", name: "Kapuváros", title: "Ahol minden történet megérkezik", theme: "Érkezés · Fuvar · Idegenek", description: "A kapuk előtt nincs biztos helyed. Itt mindenki valahonnan jön, és minden szekér hoz magával egy történetet.", longDescription: "A városfal tövében álló utcák soha nem ürülnek ki teljesen. Hajnalban rakodók és pékek kezdik a napot, délelőtt a fuvarosok és pénzváltók alkudoznak, estére pedig az utazók történetei keverednek az őrök pletykáival. Aki itt megtanul figyelni, hamarabb tudja meg, mi változik a városban, mint az, aki a belvárosban él.", art: "/assets/city-panorama.webp", accent: "#b78b4c", question: "Ki vagy, és mit hoztál magaddal?", landmarks: ["Külső Kapu", "Hárompatkós Fogadó", "Rakparti mérlegház", "Őrkapu-udvar"], streetLife: ["Hajnalban szekérkaravánok érkeznek.", "Délelőtt pénzváltók és fuvarosok hangoskodnak.", "Alkonyatkor az utazók megtöltik a fogadókat."], whispers: ["Két adóláda nem ért be tegnap.", "A keleti útról érkezett egy pecséttelen szekér.", "Az egyik kapuőr túl sokat kérdez a fekete érmékről."], npcIds: ["damar", "alma", "petar", "vera", "jarek"], openLabel: "A kapu környéke szabadon járható" },
  { id: "workshops", name: "Műhelynegyed", title: "Ahol a város keze dolgozik", theme: "Mesterség · Büszkeség · Munka", description: "Kalapácsok, kemencék és műhelyudvarok. Itt a tehetséget kézzel lehet lemérni.", longDescription: "A Műhelynegyed a Külváros legmelegebb része. Nem a nap miatt: a kemencék egész nap izzanak. A mesterek egymástól vesznek anyagot, szerszámot és munkát, és pontosan tudják, ki melyik megrendelést rontotta el tavaly. A becsület itt lassan épül fel, de egyetlen rossz munka sokáig árnyékot vet.", art: "/assets/borin-workshop.webp", accent: "#c17b42", question: "Mit tudsz létrehozni a saját kezeddel?", landmarks: ["Borin műhelyudvara", "Vörös Kemencék sora", "Kötőművesek sikátora", "Szerszámcsarnok"], streetLife: ["Délelőtt minden ajtó nyitva áll.", "Délután a műhelyekből kiáramló hő megtölti az utcát.", "Alkonyatkor a mesterek a küszöbön vitatják meg a megrendeléseket."], whispers: ["Valaki túl finom mesterjegyet másol.", "Borin egy régi pecsétet keres.", "Egy megrendelő nem akarta elárulni, kinek lesz a penge."], npcIds: ["garran", "velka", "nara", "tomen"], openLabel: "A mesterek nappal elérhetők" },
  { id: "oldMarket", name: "Régi Piac", title: "Ahol minden árnak története van", theme: "Alku · Információ · Kísértés", description: "Helyi árusok, gyors alkuk és olyan hírek, amelyeknek gyakran nincs ára — csak következménye.", longDescription: "Ez nem a nagy Kereskedelmi Központ. A Régi Piac sokkal személyesebb: itt ismerik a vevő arcát, a hazugság hangját és azt is, ki szokott késve fizetni. Egy árus pultja alatt ugyanúgy lapulhat egy hamis bélyegző, mint egy teljesen ártatlan sütemény.", art: "/assets/market-art-v3.webp", accent: "#bc9b4a", question: "Miben éri meg hinnem?", landmarks: ["Régi mérlegsor", "Tízlámpás tér", "Füstölt húsok sora", "Ponyvás órások"], streetLife: ["Reggel az alkuk még tiszták.", "Délben az információ a legdrágább áru.", "Estére a standok alatt több történet marad, mint áru."], whispers: ["Az egyik kereskedő túl pontosan tudja, melyik láda mikor érkezik.", "Valaki fekete szélű érmével fizetett.", "A Vörös Utcákból egy új közvetítő jár ide."], npcIds: ["ilren", "zora", "cador", "pell"], openLabel: "A piac egész nap lüktet" },
  { id: "redStreets", name: "Vörös Utcák", title: "Ahol a törvénynek árnyéka van", theme: "Fogadás · Alvilág · Hírnév", description: "Kopott kapualjak, fogadások és informális hatalom. Itt senki nem kérdezi, mit teszel — azt kérdezik, ki áll mögötted.", longDescription: "A Vörös Utcák nappal félálomban vannak, alkonyatkor azonban hirtelen megtelnek élettel. A fogadók ajtaja bezárul, a kártyaasztalok megjelennek, és az emberek úgy beszélnek, mintha minden mondatnak lenne egy másik értelme is. A rendőrök jelenléte érezhető, de nem mindenki fél tőlük.", art: "/assets/outskirts.webp", accent: "#9d4b42", question: "Kié az utca, amikor a törvény nincs ott?", landmarks: ["Vörös Lámpás Fogadó", "Keskeny Udvar", "Kártyások pincéje", "Törött Harang utca"], streetLife: ["Délután a fogadósok előkészülnek.", "Alkonyatkor megjönnek a fogadók és közvetítők.", "Éjjel a csend is üzletet jelent."], whispers: ["Valaki megrendez egy arénai vereséget.", "Miri ma este nincs ott, ahol lennie kellene.", "Damar kulcsai közül egy hiányzik."], npcIds: ["miri", "havel", "brenka", "silas", "tosk"], openLabel: "Alkonyatkor változik meg igazán" },
  { id: "watch", name: "Őrségi Negyed", title: "Ahol minden történetnek jegyzőkönyve van", theme: "Rend · Bizonyíték · Intézmény", description: "Őrök, fogda, nyilvántartás és azok az ajtók, amelyek csak hivatalos kulccsal nyílnak.", longDescription: "Az Őrségi Negyed nem erőd. Inkább egy gépezet: bejövő jelentések, pecsétek, váltások, kihallgatások és fogdák alkotják. Itt a szó önmagában kevés. Dátum, tanú és tárgyi bizonyíték kell hozzá. Aki túl sokáig dolgozik itt, megtanulja, hogy a rend és az igazság nem mindig ugyanaz.", art: "/assets/inner-city.webp", accent: "#64809a", question: "Mi számít rendnek, és ki dönt róla?", landmarks: ["Őrkapu-udvar", "Pecsételő iroda", "Kisfogda", "Jelentőterem"], streetLife: ["Váltáskor a negyed egy pillanatra teljesen megtelik.", "Napközben mindenki papírt keres.", "Éjjel csak a járőrök és az őrnaplók maradnak."], whispers: ["Rovan egy fekete pecsétet tart magánál.", "Két jelentés nem ugyanarról az ügyről szól.", "Valaki túl gyakran jár a raktáraknál."], npcIds: ["rovan", "lena", "bran", "orren"], openLabel: "Hivatalos ügyekhez kötött" },
  { id: "oldEdge", name: "Régi Perem", title: "Ahol a város elfelejtette a saját múltját", theme: "Emlék · Rejtély · A Szem", description: "Elfalazott ajtók, régi kövek és olyan jelek, amelyekről a legtöbb ember inkább nem kérdez.", longDescription: "A Régi Perem a Külváros legcsendesebb része. A házak között már nincs rendes utca, csak ösvények és elhasznált kőlapok. Egykor itt állhatott valami fontosabb, mint egy külvárosi raktárnegyed. A falakon néha olyan jelek jelennek meg újra, amelyeket nappal senki sem akar észrevenni.", art: "/assets/forest.webp", accent: "#6e8364", question: "Mi volt itt előttünk?", landmarks: ["Elfalazott kapu", "Régi raktárudvar", "Kopott körfal", "A néma kút"], streetLife: ["Nappal ritkán jár erre bárki.", "Alkonyatkor a kövek hosszú árnyékokat vetnek.", "Éjjel a legtöbb ember kerülőt választ."], whispers: ["A falon újra megjelent egy régi jel.", "Eldra egyszer ide küldött valakit.", "A Szem nem először figyeli ezt a helyet."], npcIds: ["eldra", "siven", "maela"], openLabel: "A történet nyitja meg" },
];

