export const NPC_STORIES: Record<string, NpcStoryProfile> = {
  miri: { history: 'Miri kilencévesen egy szekér alatt aludt, amikor a téli ködben eltűnt az anyja. Senki nem kereste sokáig; a Külváros túl sok embert nyel el ahhoz, hogy egyetlen név megállítsa az utcát. Miri akkor tanulta meg, hogy aki emlékezni akar valamire, annak előbb meg kell tanulnia kérdezni. Azóta a város titkait nem gyűjteménynek, hanem adósságok hálójának tekinti.', motivation: 'Saját információs hálózatot épít, amelyben senki nem birtokolhatja egyedül az igazságot. Mélyen belül még mindig azt az embert keresi, aki egyszer tudta, mi történt azon a ködös éjszakán.', secret: 'Egyszer eladott egy nevet egy pénzzel teli férfinak. Másnap az a név eltűnt a városból, és Miri azóta minden nevet kétszer ellenőriz, mielőtt kimondja.', questRole: 'Az első ember, aki megtanítja a játékost: a városban az információ éppúgy árucikk, mint a vas vagy a kenyér.' },
  rovan: { history: 'Rovan apja katonatiszt volt, és arra tanította, hogy a parancs akkor is parancs, ha rossz ember adja. Rovan fiatalon épp ezt az örökséget tagadta meg: egy éjszakai őrjáraton visszafordult egy eltűnt őrért, miközben a hivatalos utasítás szerint tovább kellett volna mennie. A társát megmentette, a rangját egy időre elveszítette, és megtanulta, hogy a törvénynek ára van.', motivation: 'Bizonyítani akarja, hogy a rend nem egyenlő a vak engedelmességgel. A játékosban is ezt a különbséget keresi: szabálykövetőt vagy felelősséget vállaló embert lát-e benne.', secret: 'Egy régi bizonyítékláda eltűnésében talán nem ő volt hibás, de valaki az ő aláírását használta. A hiányzó ládát azóta is keresi, mert tudja, hogy egyszer még visszatérhet.', questRole: 'A fő történet hivatalos gerince és az első ember, aki a játékosnak megmutatja, hogy a becsületnek néha személyes ára van.' },
  damar: { history: 'Damar rakodófiúként kezdte a rakpart felé vezető raktárak között. Nem a falak elhelyezkedését tanulta meg először, hanem azt, melyik padlódeszka nyikorog, melyik felügyelő hazudik és melyik láda mozog akkor is, amikor papíron nem szabadna. Évek alatt a raktárak emberi térképévé vált.', motivation: 'Azt akarja, hogy a láncok között végre legyen valaki, aki tudja, mi érkezik és mi tűnik el. A saját életét elvesztett rakományokban méri, ezért számára minden hiány személyes ügy.', secret: 'Egy régi kulcsot évekkel korábban átadott valakinek, mert azt hitte, munkát ad egy rászorulónak. Azóta sem tudja, hogy az a kulcs hány ajtót nyitott ki.', questRole: 'Az árumozgás első emberi térképe, aki a Külvárosból lassan a kikötő és a nagy kereskedelmi hálózat felé vezeti a játékost.' },
  garran: { history: 'Borin Vasmarok apja műhelyében nőtt fel, ahol a kalapács hangját hamarabb tanulta meg, mint az írást. A mestere azt verte a fejébe: a jó penge nem attól jó, hogy éles, hanem attól, hogy nem hagyja magára azt, aki rábízza az életét. Borin egyetlen alkalommal mégis olcsó anyagból kényszerült dolgozni, és egy ember megsérült. Azóta minden tárgyon megkeresi a saját felelősségének súlyát.', motivation: 'A műhelyt önállóan akarja megvédeni a céhes függéstől, és olyan fegyvereket készíteni, amelyeket nem kell szégyellni a következő csata után.', secret: 'Ismeri egy régi mesterpecsét eredetét, és tudja, hogy az egyik fekete jelölt fémdarab nem egyszerűen kereskedelmi áru.', questRole: 'A játékos első valódi mesteremberi kapcsolata; nála tanulja meg, hogy a tárgyaknak is van múltjuk, ára és felelősségük.' },
  eldra: { history: 'Eldra vándorló laboratóriumok között nőtt fel, ahol az üvegek helyén néha lakókocsik álltak, a kísérletek helyén pedig éjszakai tábortűz. Mesterei megtanították neki, hogy az ismeretlen anyaggal nem szabad erőből bánni; előbb meg kell hallgatni, hogyan reagál. A Külvárosban azért maradt, mert itt talált egy port, amelyhez ugyanazt a csendet érezte, mint gyerekkorában egy elfeledett romnál.', motivation: 'Meg akarja érteni, miért reagálnak bizonyos anyagok a Fekete Érme nyomaira. Nem hatalmat keres, hanem magyarázatot — és talán felmentést arra a dologra, amit egykor a laborban tett.', secret: 'A Fekete Érme porának egyik összetevőjét már látta egy sokkal régebbi tárgyon. Soha nem beszélt róla, mert attól fél, hogy a két történet ugyanoda vezet.', questRole: 'A történet természetfeletti érzékelője, aki úgy nyitja meg a nagyobb rejtélyt, hogy közben ember marad, nem mindent tudó bölcs.' },
  velka: { history: 'Velka katonai beszállító családban született, ahol a rendelések fontosabbak voltak az embereknél. Gyerekként gyakran látott olyan páncélt visszakerülni, amelynek hibáit a hivatalos műhelyek sosem írták le. Egy nap az apja elé tett egy hibás sisakot, és megkérdezte, ki fogja viselni. A válasz óta saját műhelyt akar.', motivation: 'Tartós páncélt akar készíteni azoknak is, akik nem tudnak vagyonokat fizetni. Nem szereti a hősöket; inkább azt becsüli, aki hazatér.', secret: 'Tudja, hogy egy sor hibás fémbetétszállítmány ugyanonnan érkezett. A beszállító nevét ismeri, de egy ideig nem merte kimondani.', questRole: 'A minőség, tisztesség és felelősség szála; rajta keresztül a játékos megtapasztalja, hogy egy rossz tárgy emberéletet jelenthet.' },
  alma: { history: 'Alma egy vándorcsalád fogadójában nőtt fel, ahol minden este más nyelven szóltak a történetek. Gyerekként nem a vendégeket figyelte, hanem azt, mikor lett csend egy asztalnál. Később rájött, hogy a legfontosabb dolgokat gyakran azok mondják el, akik azt hiszik, senki sem figyel rájuk.', motivation: 'Azt akarja, hogy a fogadó biztonságos hely maradjon annak is, aki pénz nélkül érkezik. Közben a pletykákból próbálja összerakni, milyen városban él valójában.', secret: 'Egy eltűnt vendég csomagját évek óta őrzi a padláson. Nem tudja, mi van benne, csak azt, hogy a tulajdonosa soha nem tért vissza érte.', questRole: 'A világ hangulati emlékezete és az első NPC, akitől a játékos érzi, hogy a városnak nemcsak hivatalos története van.' },
  petar: { history: 'Petar lovak között nőtt fel, és hamar rájött, hogy az állat előbb veszi észre a veszélyt, mint az ember. Első útján egy özvegy család élelmét vitte át viharban, és rájött, hogy a fuvarozás nem tárgyakat, hanem reményeket mozgat. Azóta nem szereti a céheket, mert túl sokszor látta, hogy a papír felülírja az utat.', motivation: 'Szabad akar maradni a céhektől és útvonalengedélyektől. Olyan fuvarokat szeretne, amelyekben a szavát többre tartják, mint a pecsétet.', secret: 'Egy alkalommal tudatosan vitt el egy rakományt egy lezárt úton. Nem a pénz miatt tette, hanem mert tudta, hogy a megrendelő másnap nélkülözni fogja.', questRole: 'Az utak, utazás és kockázat emberi arca, aki mindig megmutatja, hogy a térkép mögött emberek is utaznak.' },
  vera: { history: 'Vera családja pénzváltó volt, és gyermekkorában az érméket nem számolni, hanem hallgatni tanulta: egy tiszta érme másként üt a rézhez, mint egy öntött hamisítvány. Apja halála után ő maradt a kis pult mögött, és megtanulta, hogy a pénz mögött mindig van valaki, aki fél elveszíteni.', motivation: 'Azt akarja, hogy ne lehessen könnyen átverni azokat, akik nem értik a pénzt. A saját szegénységét nem akarja romantikussá tenni; számára az arany azt jelenti, hogy egy család ma eszik-e.', secret: 'Egy fekete szegélyű érmét már évekkel korábban látott. Akkor még azt hitte, hibás darab. Később rájött, hogy túl sok helyen bukkant fel ugyanaz a hiba.', questRole: 'A hamis pénz korai bizonyítéka és a játékos első találkozása azzal, hogy a Fekete Érme nem egyedi furcsaság.' },
  jarek: { history: 'Jarek egy összeomlott térképészeti műhelyben tanulta a mesterségét, ahol régi országutak másolatait javították. Mestere mindig azt mondta: aki kitöröl egy utat, az két dolgot tesz egyszerre — eltünteti az utazót és az emléket. Jarek ezt soha nem felejtette el.', motivation: 'Azt akarja, hogy a város minden kijárata és elfeledett útja ismert legyen. A térképet nem rajznak, hanem felelősségnek tekinti.', secret: 'Egy térképről szándékosan kitörölt egy útvonalat valaki kérésére. Azóta sem tudja, hogy azzal egy embert mentett meg, vagy egy üldözőt segített megtéveszteni.', questRole: 'A világ geometriájának őre, akinek segítségével a játékos megérti, hogy a város elhallgatott útjai is történeteket hordoznak.' },
  nara: { history: 'Nara egy cserzőcsaládban nőtt fel, ahol a bőr szagából már gyerekként felismerte, milyen állatból és melyik vidékről származik. Egy kereskedő egyszer felismerhetetlen hamis bőrrel fizetett a családjának. Nara akkor döntötte el, hogy soha többé nem fogad el árut látatlanul.', motivation: 'Saját, tiszta beszállítói láncot akar létrehozni, amelyben tudja, kihez tartozik minden darab.', secret: 'Egy ritka bőrt egy olyan hajóról kapott, amelynek hivatalosan nem kellett volna befutnia. A bőrbe varrt jel nem kereskedelmi jel volt.', questRole: 'A kereskedelmi hálózat emberi belépési pontja, ahol az áru eredete először fontosabb lesz az áránál.' },
  tomen: { history: 'Tomen tanoncként minden műhelyből elles valamit, de egyikben sem maradt sokáig. Nem azért, mert lusta, hanem mert minden mestertől azt hallotta: „Így szoktuk.” Ő pedig mindig megkérdezte, miért. Ezzel több mestert elveszített, mint amennyit szerzett.', motivation: 'Mestert akar találni, aki valóban tanítja, nem csak dolgoztatja. A saját nevét nem szeretné egy műhelyhez kötni addig, amíg nem érzi, hogy megérdemli.', secret: 'Egy régi szerszámon olyan jelet talált, amelyet senki sem mert megmagyarázni. A jel visszatér az első fekete pecsét történetében.', questRole: 'A fiatal szem perspektívája: azt mutatja meg, hogyan öröklődnek a hibák, és hogy egy új nemzedék néha hamarabb kérdez, mint válaszol.' },
  zora: { history: 'Zora családja fűszerekkel kereskedett, ő pedig az illatokból tanulta meg a hajók eredetét. Ismerte a tengeri só, a szárított gyökér és a szegfűszeg keverékét úgy, mint más az arcokat. Egy rakományon azonban egyszer olyan illatot érzett, amelynek nem kellett volna a városban lennie.', motivation: 'A ritka áruk útját akarja feltérképezni, mert úgy gondolja, a kereskedelem pontosabb történelem, mint a királyi könyvek.', secret: 'Egy hajó rakományáról tudja, hogy a hivatalos vámjegyzék hazudik. A rakomány között valami más is érkezett, nem csak fűszer.', questRole: 'A kikötő felé vezető illat- és áruösvény; a játékos tőle tanulja meg először, hogy bizonyos áruknak saját emlékezetük van.' },
  cador: { history: 'Cador csendes könyvelőként dolgozott több kereskedő mellett, és közben rájött, hogy a számok nem hazudnak — csak az emberek tanítják őket hazudni. Évekig nézte, hogyan tűnnek el kis összegek, míg egyik hónapban hirtelen egy egész útvonal hiányzott a könyvekből.', motivation: 'Azt akarja, hogy a számok végre ne csak a hatalmasokat szolgálják. Nem hős akar lenni; azt szeretné, hogy a bizonyíték ne váljon alku tárgyává.', secret: 'Egy régi könyvben már megtalálta ugyanazt a mintát, de eltüntette a bizonyítékot, mert félt, hogy a családját is eléri az ügy.', questRole: 'A főkönyvi logika egyik kulcsfigurája, aki a Fekete Érmét először rendszerként láttatja.' },
  pell: { history: 'Pell a piacon nőtt fel, ahol az ember értékét nem a ruhája, hanem az határozza meg, hányszor tér vissza ugyanahhoz az asztalhoz. Gyerekként ládák mellett aludt, és a kofák történeteiből tanulta meg, hogy a pletyka mindig egy kicsit igaz.', motivation: 'Megélni akar, de közben érzi, hogy a hallott történetekből egyszer saját értéket teremthet. Nem akar nagy ember lenni; azt szeretné, hogy az emberek ne nézzék át.', secret: 'Néhány éve egy idegen férfi minden héten ugyanazt a gyümölcsöt kérte tőle, mindig más néven. Pell tudja, hogy a név változott, de az ember nem.', questRole: 'Az utca információs érzékelője, aki megmutatja, hogy a város legfontosabb hírei sokszor nem a hivatalokból indulnak.' },
  havel: { history: 'Havel egykor komoly kártyaadósságot szedett össze, és egyetlen éjszakán elvesztette a családi örökségét. Azóta fogadót vezet, mert úgy gondolja, hogy a vesztes embernek is kell egy szék, ahová leülhet. A játékot nem szereti, de az emberi pillanatot igen.', motivation: 'Azt akarja, hogy az emberek még a vereség után is megőrizhessék a méltóságukat. Ezért figyeli túl élesen azokat, akik már nem tudják, mikor kell felállniuk az asztaltól.', secret: 'Egykor fekete peremű érméket látott egy titkos asztalon. Egyet megőrzött, de azt mondja mindenkinek, hogy régen elvesztette.', questRole: 'A szerencse és veszteség első narratív kapuja, aki megmutatja, hogy a pénz mögött gyakran szégyen és vágy is van.' },
  brenka: { history: 'Brenka oddsokat tanult egy arénai pénzembertől, aki egyszer azt mondta neki: a jó bukméker nem azt tudja, ki nyer, hanem azt, ki mennyit fogad rá. Brenka megtanulta a számokat, de közben az emberek tekintetét is.', motivation: 'Azt akarja, hogy minden fogadás mögött ő irányítsa az információt. Nem a pénzért él; azért, hogy senki ne tudja, mikor hazudik a számítás.', secret: 'Egy nagy játékosnak rendszeresen előre jelzi, melyik mérkőzés lesz gyanús. Cserébe sosem kér pénzt — csak neveket.', questRole: 'A PvP gazdaság és a Fekete Érme pénzmozgásának összekötője.' },
  silas: { history: 'Silas utcai közvetítőként nőtt fel, és hamar rájött, hogy a legjobb üzlet az, amelyben egyik fél sem tudja, kitől jött az ajánlat. Fiatalon sokáig futár volt, később saját hálózatot épített. Minden kapcsolata mögött ott maradt egy fél elmondott mondat.', motivation: 'Saját hálózatot akar, amelyhez nem kell senkinek esküt tennie. Nem akar vezető lenni, mert a vezetőket könnyű megtalálni.', secret: 'Egy ideig ugyanannak a névtelen megbízónak dolgozott, aki most a Fekete Érme nyomában van. A hangjára még mindig emlékszik.', questRole: 'A rejtett társadalmi háló kapuja, ahol a játékos először érezheti, milyen, amikor egy történetnek nincs hivatalos arca.' },
  tosk: { history: 'Tosk sokáig csak ajtókat őrzött, míg rá nem jött, hogy néha az ajtó mögötti ember fontosabb. A szolgálat évei alatt megszokta, hogy minden belépés valaki más döntése. Ezt a világképet mostanra kissé megbánta.', motivation: 'A határokat akarja ellenőrizni, nem az embereket. Titokban azt szeretné, ha egyszer olyan helyen dolgozhatna, ahol ajtót nyitni ugyanúgy lehet becsület, mint bezárni.', secret: 'Tud egy pinceajtóról, amelyet a város hivatalosan nem ismer. Évekkel ezelőtt megpróbálta megmutatni, de akinek szólt, másnap elhagyta a várost.', questRole: 'Belépések és rejtett terek őre; rajta keresztül a játékos megtanulja, hogy hozzáférést gyakran nem kulccsal, hanem bizalommal szerez az ember.' },
  lena: { history: 'Lena több hivatal alatt szolgált, mire rájött, hogy a papír ugyanúgy emlékszik, mint az ember. Gyerekként azt hitte, a törvények kőbe vannak írva. Felnőttként azt látta, hogy néha egy tollvonás több életet változtat meg, mint egy kard.', motivation: 'A város hivatalos emlékezetét akarja tisztán tartani. Nem szereti a hősöket; az ellenőrizhető igazságot szereti.', secret: 'Egy hiányzó pecsétet egyszer ő maga tett el, hogy megakadályozzon egy igazságtalanságot. A döntést azóta sem tartja teljesen helyesnek.', questRole: 'A bürokrácia morális oldala, amelyből később a Palota történeti bizonyítékai nőnek ki.' },
  bran: { history: 'Bran katonaként szolgált, mielőtt a fogdát választotta, mert csendesebbnek hitte a felelősséget. Tévedett. A cellákban minden ember története rövidebb mondatokban érkezik, és néha egyetlen elhallgatott sor többet jelent, mint egy teljes vallomás.', motivation: 'Azt akarja, hogy a fogda ne legyen bosszú eszköze. Aki hibázott, fizessen érte, de ne tűnjön el csak azért, mert senki sem hallja.', secret: 'Egy fogvatartottat egyszer éjjel úgy engedtek ki, hogy Branra kenték a felelősséget. A neve megmaradt benne, még ha az iratokból ki is törölték.', questRole: 'A főtörténet emberi árának őrzője; nála a Fekete Érme már nem papír, hanem emberi sors.' },
  orren: { history: 'Orren egész életét őrjáratban töltötte, ezért jobban ismeri a város ritmusát, mint a törvényeit. Tudja, melyik ablakban alszik későn egy gyermek, melyik sikátorban alszik túl sokáig egy kutya, és mikor csúszik el néhány perccel a város rendje.', motivation: 'Azt akarja, hogy a városban ne lehessen ugyanazt a trükköt kétszer eljátszani. A rend számára nem merev szabály, hanem ismétlődő minták felismerése.', secret: 'Tudja, hogy minden este ugyanabban a hatperces résben eltűnik az őrségi lánc. Soha nem derült ki, ki használja ki ezt a rést.', questRole: 'Az idő, útvonal és rend találkozási pontja, aki a szerveróra és a világ valódi ritmusát narratív eszközzé emeli.' },
  siven: { history: 'Siven romvadászként olyan tárgyakat keres, amelyek túl régiek ahhoz, hogy a város megértse őket. Gyermekkorában egy romlott falból húzott ki egy követ, és amikor az éjszaka ráborult, pontosan úgy érezte, mintha valaki visszanézne rá.', motivation: 'A régi város eredetét akarja feltárni. Nem kincset keres; azt akarja tudni, miért épült valami ott, ahol most már csak kövek maradtak.', secret: 'Egy régi kőjelről tudja, hogy ugyanazt a mintát használja, mint a fekete tinta. Ettől sokkal jobban fél, mint amennyit mutat.', questRole: 'A Fekete Érme mélyebb, régebbi eredetének nyomozója és A Szem előtti világ egyik első kapuja.' },
  maela: { history: 'Maela egész életében a néma kút körül élt. Anyjától azt tanulta, hogy a víz nem beszél, de visszaadja, amit beledobtak. Maela ezért minden apró változást észrevesz: más hang, más visszhang, más szag, más csend.', motivation: 'Azt akarja, hogy a Régi Perem ne tűnjön el a város történetéből. Mindenki azt mondja, ide már nem érdemes építeni; ő azt mondja, ide még érdemes emlékezni.', secret: 'A kút alatt valaha egy teljesen más épületrendszer nyílhatott. Egyszer hallott valamit odalentről, ami nem víz volt.', questRole: 'A Külváros rejtett mélységének őrzője; az első hely, ahol a város múltja nem emberi emlékezetként, hanem térként tér vissza.' },
  arenaSena: { history: 'Sena vándorküzdőként érkezett a fővárosba egyetlen karddal és egy eltört csuklóval. Az első próbakapunál nem győzött; csak nem esett el. A közönség ezt kinevette, az öreg edző viszont azt mondta, a tehetség néha azon látszik, hogy valaki mit csinál a vereség után. Sena maradt.', motivation: 'Azt akarja, hogy a tehetséget ne a származás, hanem a teljesítmény döntse el. A saját példájával akarja áttörni azt a láthatatlan falat, amely a gazdag és a szegény harcosokat elválasztja.', secret: 'Egyszer elveszített egy mérkőzést, mert nem engedelmeskedett egy manipulált bírói jelnek. Azóta tudja, hogy az Aréna nem mindig azt méri, amit hirdet.', questRole: 'A játékos első arénai beavatója; az ő szemén keresztül a harc nem puszta erőpróba, hanem becsületkérdés.' },
  arenaKorr: { history: 'Korr egykor bányász volt, ahol a kő súlyából tanulta meg, hogyan olvassa a törést. Az első arénai páncélját saját kezűleg készítette, mert a boltban kapott darab eltört az első ütésnél. Azóta minden harcos felszerelésében a saját kezét érzi.', motivation: 'A harcosokat saját felelősségükre akarja megtanítani. Szerinte az erős ember nem az, aki soha nem sérül meg, hanem aki megtanulja, miért sérült meg.', secret: 'Tudja, hogy az Aréna fegyverbeszállítói közül valaki szándékosan gyenge anyagot küld. Azt is tudja, hogy ezért valakinek fizetnie kell.', questRole: 'A felszerelés és tisztesség őre; az első komoly híd az itemek, crafting és történet között.' },
  arenaVeya: { history: 'Veya gyógyítóként került az Arénába, miután egy vándorló hadsereg mellett látta, mennyi sérülés lesz láthatatlanná csak azért, mert a győzelem fontosabb. Egy harcos egyszer azt kérte tőle, hogy ne gyógyítsa meg, mert akkor másnap nem tudna küzdeni. Veya ezt a mondatot azóta sem felejti.', motivation: 'Azt akarja, hogy a győzelem ne kerüljön szükségtelen emberéletbe. Nem tiltja a harcot; csak azt követeli, hogy mindenki tudja, milyen árat fizet érte.', secret: 'Titokban listát vezet a manipulált mérkőzések után sérült harcosokról. A lista egy ponton összefut a fogadóirodák könyveivel.', questRole: 'Az Aréna emberi oldala, ahol a játékos először érti meg, hogy a győzelemnek is lehet sebe.' },
  arenaBram: { history: 'Bram utcai történetmondóból lett műsorkiáltó. Azt hitte, a hangja csak a közönségnek kell, míg egyszer egy tömeg egyetlen félreértett mondat miatt fellázadt. Azóta minden kimondott szót súlyosabbnak érez.', motivation: 'Akaratlanul is ő irányítja, miről beszél a közönség, és ezt félti a legjobban. Nem akar uralkodni a tömegen; azt akarja, hogy ne uralkodjanak rajta mások.', secret: 'Valaki fizet neki azért, hogy bizonyos neveket soha ne mondjon ki. Bram nem tudja, miért fontosak ezek a nevek, csak azt tudja, hogy mind ugyanazon a könyvben szerepelnek.', questRole: 'A hírnév és tömegek feletti befolyás kulcsa; rajta keresztül a történet hangja eljut az egész Arénához.' },
  arenaRusk: { history: 'Rusk számolóként kezdett, mert gyerekként képtelen volt elhinni, hogy egy kockadobás csak szerencse. Később rájött, hogy az emberek hajlandók még a saját veszteségükre is fogadni, ha azt szeretnék hinni, hogy irányítják. Ekkor fordult a fogadások felé.', motivation: 'Azt akarja, hogy minden kockázat kiszámítható legyen. A veszélyt nem gyűlöli, csak azt nem szereti, ha valaki hazudik arról, mekkora.', secret: 'Titkos oddsot vezet olyan mérkőzésekhez, amelyek hivatalosan nem is léteznek. Az adatok között ugyanaz a pénzügyi ritmus ismétlődik, mint a Fekete Érménél.', questRole: 'A fekete pénz arénai pénzügyi térképe és a nagyobb gazdasági összeesküvés egyik első bizonyítékforrása.' },
  arenaTalia: { history: 'Talia egykori bajnokként a testén több heget visel, mint kitüntetést. Az egyik döntőben nyert, de utána látta, hogy az ellenfele soha többé nem küzdött. Azóta a győzelmet nem a dobogón, hanem abban méri, hogy mit hagy maga után.', motivation: 'Azt akarja, hogy a rang valódi teljesítményt jelentsen. Neves embereket különösen nehezen enged át a próbákon.', secret: 'Egy régi bajnoknak tartozik egy döntéssel, amelyet soha nem hozott meg. A tartozás évekkel később is meghatározhatja, kit enged az élre.', questRole: 'A játékos fejlődési útjának kapuőre; a rang mögé emberi történetet tesz.' },
  arenaOlen: { history: 'Olen fegyvermesterként a részletekben látja a csalást. Egy apró reszelési nyom, egy hibás szegecs, egy elcsúszott súly — számára mind vallomás. Egyszer egy fegyveren ugyanazt a jelet találta, mint egy régi királyi ládán. Nem szólt róla senkinek.', motivation: 'Azt akarja, hogy minden harcos azt a fegyvert használja, amelyért felelősséget vállal. Nem hisz a szerencsében, csak az előkészítésben.', secret: 'Egy beszállító pecsétjét már látta a Fekete Érme egyik iratán. A pecsét nem arénai eredetű.', questRole: 'A tárgyi bizonyítékok arénai specialistája; ő köti össze a felszerelést a történet rejtett hálójával.' },
  serin: { history: 'Serin egykor bajnok volt, és egyetlen vereség után soha többé nem lépett a homokra. Nem azért, mert félt, hanem mert rájött, hogy a meccset előre eladták. Azóta mások döntéseit figyeli, mert sajátját már egyszer elvették tőle.', motivation: 'Azt akarja, hogy a győzelem mellett a következmények is számítsanak. A játékosban azt keresi, van-e ára annak, amit hajlandó megtenni a sikerért.', secret: 'Tudja, hogy egy nagyobb ügy folyik a fogadások alatt, és évek óta gyűjti a nyomokat. Egy részét szándékosan elrejtette a bajnoki fal mögött.', questRole: 'A Fekete Érme arénai főszereplője és az egyik első NPC, aki a játékost valódi történeti szövetségesként kezdi kezelni.' },
  ilren: { history: 'Ilren családja generációk óta kereskedett, de ő már gyermekkorában látta, hogy ugyanazt a ládát háromszor is el lehet adni, ha az ember jól nevezi át. Apja azt tanította neki, hogy a piacon minden ár magában hordozza a félelmet is. Ilren ebből épített rendszert.', motivation: 'Azt akarja, hogy a piac ne legyen kiszolgáltatva egyetlen hatalomnak sem. A szabadság számára nem romantika, hanem az, hogy több út maradjon egyetlen pénzügyi döntés mögött.', secret: 'Több tranzakcióról tudja, hogy valódi céljuk nem az áru, hanem a pénz mozgatása. Egy ilyen tranzakció nyoma a Fekete Érme felé mutat.', questRole: 'A Kereskedelmi Központ fő gazdasági csomópontja; rajta keresztül a játékos érti meg, hogy az érméknek útjuk van.' },
  malk: { history: 'Malk első karavánját tizenhét évesen vezette át egy vihar után. Az út felénél elfogyott a víz, de egy öreg sofőr megmutatta, hogyan olvasson a tájból. Azóta minden indulás előtt ugyanazt a kötelet köti fel az első kerékre, emlékként.', motivation: 'Olyan útvonalakat akar, amelyek a várost a világ többi részével összekötik. A veszélyt elfogadja, a fölösleges veszteséget nem.', secret: 'Egyik korábbi járata sosem érkezett meg, és tudja, hogy nem baleset volt. A hivatalos jelentés szerint igen.', questRole: 'A logisztika és a külvilág kapuja, aki a későbbi városok és világok felé készíti elő az utat.' },
  sera: { history: 'Sera céhes családba született, ahol a pecséteket többre tartották, mint az embereket. Ő mindig azt nézte, ki áll a papír mögött. Egy tanítvány egyszer megkérdezte tőle, miért ilyen fontos a szabály. Sera azt felelte: csak akkor, ha valaki betartja, amikor neki is fáj.', motivation: 'A szabályokat úgy akarja használni, hogy valódi szakembereket védjen, ne azokat, akiknek van pénzük megvenni a szabályt.', secret: 'Egy céhes pecsétet visszatartott valakitől, mert tudta, hogy illegális üzlethez kell. Ezzel egy gazdag ember haragját vonta magára.', questRole: 'A hivatalos kereskedelmi világ kulcsfigurája; a játékos rajta keresztül érti meg, hogy az engedély is hatalom.' },
  oris: { history: 'Oris egész életét leltárak között töltötte. Már gyerekként kiszúrta, ha egy almás ládában egyetlen gyümölccsel kevesebb volt. Nem a hiány zavarja, hanem az, amikor valaki azt akarja elhitetni, hogy nem is volt ott.', motivation: 'Azt akarja, hogy a raktárak rendje ne legyen manipulálható. A könyvek és a falak között ugyanazt a rendet keresi.', secret: 'Egy teljes szállítmány hiányzik a könyveiből úgy, hogy fizikailag egyszer már látta. Valaki később átírta a papírokat.', questRole: 'A raktárhálózat fő bizonyítékőre és a Fekete Érme árumozgásának egyik legmegbízhatóbb tanúja.' },
  niven: { history: 'Niven ritka áruk kereskedőjeként abból élt, hogy olyan dolgokat ismert fel, amelyekre más csak rámutatott. Egy drága tárgy egyszer majdnem az életébe került, mert kiderült róla, hogy nem neki szánták. Azóta minden ritkaság mögött tulajdonost keres.', motivation: 'A különlegességet keresi, nem a mennyiséget. Szerinte az érték sokszor abban rejlik, hogy egy tárgynak van-e története.', secret: 'Egy olyan tárgyat tart, amelynek eredetét a Palota is kereshetné. Soha nem kérdezte meg, mit ér; csak azt tudja, hogy veszélyes.', questRole: 'A ritka áruk és titkos szállítmányok közvetítője; később különleges itemek és történeti tárgyak kapuja.' },
  taris: { history: 'Taris közvetítőként abból él, hogy mások nem tudnak ugyanarról megegyezni. Gyermekkorában két szomszéd család vitáját úgy oldotta meg, hogy mindkettő azt hitte, ő nyert. Azóta tudja: az embernek néha a saját igazsága fontosabb, mint a tényleges eredmény.', motivation: 'Olyan üzleteket akar létrehozni, amelyekben minden fél azt hiszi, ő nyert. Mélyen belül attól fél, hogy egyszer olyan konfliktusba kerül, ahol nincs középút.', secret: 'Ismeri egy belvárosi adósságspirál egyik első láncszemét. A neve miatt egyszer már megpróbálták megfélemlíteni.', questRole: 'Az alkuk és rejtett feltételek mestere, aki a játékos társasági és gazdasági mozgásterét tágítja.' },
  cassian: { history: 'Cassian bankárként nem az aranyat, hanem az emlékezetét védi. Egy rosszul vezetett könyv miatt apja elvesztette a házát, ezért gyermekkorában megtanulta, hogy egyetlen kihúzott sor családokat dönthet romba.', motivation: 'Azt akarja, hogy a tartozások kiszámíthatóak maradjanak, még akkor is, ha ettől néha ő veszít pénzt.', secret: 'Egy fekete pénzügyi könyv egy részét őrizte már évekkel korábban. A könyvben nem nevek voltak, hanem útvonalak.', questRole: 'A pénz és adósság fővárosi kapuja; a későbbi lecsúszás és felemelkedés kulcsszereplője.' },
  lyra: { history: 'Lyra pénzváltóként a piac minden érméjének hangját ismeri. Gyermekkorában egy idegen pénzérme miatt verekedés tört ki a családja előtt, és azóta azt kutatja, miért tud egy apró fémdarab ennyi embert megváltoztatni.', motivation: 'Az árfolyamok mögötti mozgást akarja megérteni. Nem az arany érdekli, hanem az, amikor valaki eltünteti az egyik helyről, hogy máshol felbukkanjon.', secret: 'A fekete szegélyű érmék nem ugyanonnan származnak. Legalább három különböző pénzverés nyoma látszik rajtuk.', questRole: 'A pénz fizikájának és mozgásának specialistája; a Fekete Érme több eredetűségére utaló korai nyom.' },
  fen: { history: 'Fen karavánbrókerként abból él, hogy mások kockázatát számokká alakítja. Egyetlen útvonalon veszítette el a testvérét, mert a papíron „biztonságosnak” jelölt út valójában nem volt az. Azóta minden szám mellé odaírja, ki fizeti meg, ha téved.', motivation: 'Azt akarja, hogy minden út ára előre látható legyen. A veszélyt nem tudja eltüntetni, de szerinte legalább az árát ki lehet mondani.', secret: 'Egyszer tudatosan elhallgatott egy veszélyes útvonalat egy nagy ügyfél miatt. A döntésével pénzt nyert és egy embert elveszített.', questRole: 'A kockázat és utazás gazdasági oldala, a kereskedelmi utak emberi árának hordozója.' },
  marwen: { history: 'Marwen raktári felügyelőként pecséteket és embereket figyel. Fiatalkorában egy egész raktár égett le, miközben a hivatalos könyv szerint minden rendben volt. Marwen azóta a papírnál jobban hisz a hamuban.', motivation: 'Azt akarja, hogy a raktárak ne legyenek fekete zónák, ahol bármit el lehet tüntetni.', secret: 'Egy zárolt raktárt egyszer már kinyitottak az ő pecsétjével. Tudja, hogy valaki lemásolta, és azóta minden viaszlenyomatot eltesz.', questRole: 'A hivatalos ellenőrzés és rejtett árumozgás kulcsa.' },
  adrian: { history: 'Adrian házfelügyelőként évek alatt tanulta meg az elit bemutatási rendjét. Gyermekkorában ő takarította egy nagyház folyosóit, és egyszer egy bezárt ajtó mögül hallott egy beszélgetést, amely egész életét megváltoztatta. Megtanulta: az ajtó nem a szobát rejti, hanem azt, aki odabent dönt.', motivation: 'Azt akarja, hogy a megfelelő emberek valódi esélyt kapjanak, és ne csak a családnevük döntse el, hová léphetnek be.', secret: 'Egyszer valakit beengedett egy ajtón, akinek nem lett volna szabad belépnie. Azóta sem tudja, hogy ezzel kit mentett meg, és kit sodort veszélybe.', questRole: 'A társadalmi felemelkedés és kapcsolatok első kapuja.' },
  selene: { history: 'Selene a társasági életben nőtt fel, és már fiatalon megtanulta olvasni a csendeket. Egy vacsorán egyszer mindenki mosolygott, miközben az asztal alatt egy házasság sorsa dőlt el. Azóta a kimondatlan mondatokat jobban figyeli, mint a beszédet.', motivation: 'Azt akarja, hogy a szalonok ne váljanak puszta hatalmi eszközzé. A társaságot művészetnek tekinti, de tudja, milyen könnyű abból fegyvert csinálni.', secret: 'Egy vendéglistán egy befolyásos ember neve fölött egy fekete jel szerepel. Selene nem tudja, ki rajzolta oda.', questRole: 'A pletyka, kapcsolatok és társadalmi pozíció mestere.' },
  marcell: { history: 'Marcell családi játékteremből épített magának nagyobb hálózatot. Gyerekként azt hitte, a játék a szerencséről szól, majd egyetlen fogadó apja teljes vagyonát elvesztette előtte. Marcell azóta a döntéseket figyeli, és tudja, mikor válik a kockázat önpusztítássá.', motivation: 'A szerencse helyett az emberi döntéseket szereti. Azt akarja, hogy az asztalnál mindenki tudja, mit kockáztat, még ha egyikük sem akarja beismerni.', secret: 'Egyetlen játékosnak évek óta egyenesen adósságot vezet. Nem azért, mert nincs pénze, hanem mert a tartozás egy régi ígéret ára.', questRole: 'A szerencsejáték és veszteség történeti kapuja.' },
  livia: { history: 'Livia hitelközvetítőként abból él, hogy az emberek jövőbeli pénzét jelen idejű döntéssé teszi. Anyja egyetlen rossz kölcsön miatt veszítette el a családi műhelyt. Livia azóta minden szerződésben először azt keresi, mi történik a legrosszabb napon.', motivation: 'Azt akarja, hogy minden kölcsönnek tisztességes ára legyen, még ha a Belvárosban ezt sokan gyengeségnek is tartják.', secret: 'Egy nagy adósságcsomag végső kedvezményezettje ismeretlen. A neve időnként felbukkan a Fekete Érme pénzmozgásaiban.', questRole: 'A belvárosi lecsúszás és felemelkedés kulcsa; nála a pénzügyi döntés már életirányt is jelent.' },
  octavia: { history: 'Octavia művészcsaládba született, de a családi név mögött saját gyűjteményt épített. Egy festményt egyszer eladott, hogy kifizesse egy ismeretlen alkotó temetését; később megtudta, hogy a kép fontosabb volt, mint gondolta. Azóta semmit nem vesz meg pusztán szépségből.', motivation: 'A műtárgyak történetét akarja megőrizni, mert hisz benne, hogy egy tárgy néha tovább él, mint az ember, aki készítette.', secret: 'Egy darab a gyűjteményében ugyanahhoz a régi jelhez kapcsolódik, mint Eldra kutatása. A darabot nem meri nyilvánosan kiállítani.', questRole: 'A kultúra és a rejtett múlt összekötője.' },
  corvin: { history: 'Corvin a hivatalos társaság és a zárt klubok között mozog. Fiatalon ügyvéd akart lenni, de egyetlen tárgyaláson megtanulta, hogy a törvény előtt és mögött nem ugyanazok az emberek állnak. Azóta a szoba csendjét is szolgáltatásként adja el.', motivation: 'Azt akarja, hogy minden információért fizessen valaki, de ne tudja, kinek. A névtelenséget többre tartja a hatalomnál.', secret: 'Titkos naplót vezet azokról, akik a klubjában túl sokat beszélnek. Egy bejegyzés neve ugyanott szerepel, ahol a Fekete Érme útja.', questRole: 'A politikai és társadalmi háttérháló egyik őrzője.' },
  violet: { history: 'Violet egykor egyszerű fogadós volt, és egyetlen vándor tanácsa után kezdett el a Belvárosban dolgozni: „Az embereknek nem ágy kell, hanem egy hely, ahol senki sem kérdez.” A mondatot megjegyezte, de azóta többször megbánta, hányszor tartotta be.', motivation: 'A tökéletes diszkréciót tekinti szakmai becsületnek. Egy idegen életét ugyanúgy védené, mint egy királyi vendégét, ha egyszer ő lépte át a küszöbét.', secret: 'Egyetlen csomagot évek óta őriz, mert a címzett sosem jött el érte. A csomagon egy fekete viasznyom van.', questRole: 'A Belváros rejtett találkozásainak kulcsfigurája.' },
  palaceElian: { history: 'Elian udvari szolgaként kezdte, amikor még csak a tányérokat és az ajtókat ismerte. Egyetlen alkalommal egy magas rangú vendég lemondó pillantása megváltoztatta az életét: Elian rájött, hogy a palota rendjét azok tartják fenn, akiket senki sem lát.', motivation: 'A korona körül működő rendszert stabilan akarja tartani, mert tudja, milyen gyorsan törik szét egy udvar, ha senki sem tudja, mikor beszéljen és mikor hallgasson.', secret: 'Van egy saját listája arról, kik jutottak túl közel a királyhoz. A lista nem hivatalos, ezért veszélyesebb, mint az archívum.', questRole: 'A Palota bejárati kapuja, aki a játékost először a hatalom láthatatlan mechanizmusaihoz vezeti.' },
  palaceMara: { history: 'Mara több ország udvarában tanult diplomáciát, és megtanulta, hogy a béke sokkal több apró sérülést visel, mint amennyit a történelemkönyvek leírnak. Egy határháborút azért került el, mert egy vacsorán kimondott egyetlen rosszul időzített mondat helyett hallgatott. Azóta minden mondatot kétszer mér meg.', motivation: 'A konfliktusokat addig akarja kezelni, amíg még nincs szükség erőre. Azt szeretné, hogy a királyság erős legyen anélkül, hogy mindenkit ellenségnek kellene neveznie.', secret: 'Egy idegen küldöttség már kérdezett a Fekete Érméről, de aznap nem voltak benne a hivatalos látogatói listában.', questRole: 'A külső hatalmak és a főváros közti kapcsolat.' },
  palaceOrven: { history: 'Orven levéltáros családból jött, majd vizsgáló lett, mert a dokumentumoknál több igazságot akart. Gyermekként az apja egy hiányzó oldalt mutatott neki, és azt mondta: ha valami hiányzik, az nem üres hely, hanem kérdés. Orven azóta kérdéseket gyűjt.', motivation: 'Azt akarja, hogy a bizonyíték erősebb legyen a politikai akaraton. Tudja, hogy a királyság néha attól él túl, ha bizonyos dolgokat nem mondanak ki — de nem akar ilyen világban élni.', secret: 'Már évekkel korábban látott egy fekete jelhez kapcsolódó iratot. A lapot azóta sem találják az archívumban.', questRole: 'A fő történet hivatalos nyomozója és a királyi múlt egyik legfontosabb őrzője.' },
  palaceAster: { history: 'Aster gyerekkora óta őrségben szolgál, és a Palota minden ajtajának szabályát ismeri. Egy ostrom során egyszer a szabály szerint egy ajtót zárva kellett volna tartania, de egy gyermek sírását hallotta odabentről. Kinyitotta. Azóta tudja, hogy a törvény és az ember nem mindig ugyanott áll.', motivation: 'A biztonságot nem merevségnek, hanem felelősségnek tekinti. Azt akarja, hogy a Palotának legyenek határai, de ne legyen vak a kívülről jövő emberre.', secret: 'Egyszer megszegte a szabályt, hogy megmentsen valakit, és azóta sem tudja, jól tette-e. A megmentett ember később eltűnt.', questRole: 'A hatalom fizikai védelmének emberi arca.' },
  palaceYsra: { history: 'Ysra a királyi archívumban dolgozik, és a könyvek között érzi magát otthon. Gyerekként a történeteket jobban szerette, mint az embereket, mert a könyvek nem változtatták meg ugyanazt a múltat kedvük szerint. Felnőttként rájött, hogy még a könyveket is lehet manipulálni.', motivation: 'Azt akarja, hogy semmilyen történelmi igazság ne tűnjön el. A hiányzó oldalak jobban érdeklik, mint a díszes kötetek.', secret: 'Egy régi kötet hiányzik a polcokról, de a hiányát senki sem merte bejegyezni. Ysra tudja, mikor tűnt el.', questRole: 'A régi világ és a jelen összeillesztője, aki majd képes lesz igazolni, milyen messzire nyúlik vissza a Fekete Érme története.' },
  harborKael: { history: 'Kael tengerészként kezdett, majd egy viharban húsz embert vezetett vissza a partra úgy, hogy közben elvesztette a saját testvérét. Azóta minden hajót úgy ellenőriz, mintha a legénységért személyesen felelne. A rakpartot nem helynek, hanem határvonalnak tekinti.', motivation: 'Azt akarja, hogy a kikötő ne legyen senki magánbirodalma. Minden rakományhoz és minden hajóhoz arcot akar társítani.', secret: 'Egy hajó érkezését egyszer szándékosan késleltette, hogy megvédjen egy embert. Az árut később elveszettként könyvelték el.', questRole: 'A kikötő hivatalos arcának kulcsfigurája és a Fekete Érme tengeri ágának első kapuja.' },
  harborDain: { history: 'Dain írnokként minden hajót és rakjegyet fejben tart. Apja hajózási naplók mellett halt meg, ezért Dain mániákusan ragaszkodik az egyező számokhoz. Egy rakjegy egyszer mégis más számot mondott, mint a rakomány.', motivation: 'Azt akarja, hogy a papír és a valóság ugyanazt mondja.', secret: 'Egy rakjegyet már egyszer átírtak úgy, hogy ő volt az aláíró. Az eredetit megtartotta.', questRole: 'A hajózási adminisztráció bizonyítékőre; a Fekete Érme kikötői útjának egyik első szilárd pontja.' },
  harborJoren: { history: 'Joren egész életét a sós hálók között töltötte. Fiatalon ő is el akart menni, de egyszer egy viharban egy egész halászcsaládot mentett ki, és rájött, hogy van olyan élet, amely nem a távolba, hanem a helyhez való hűségből épül. Azóta maradt.', motivation: 'Azt akarja, hogy az egyszerű emberek se váljanak a nagy üzletek áldozataivá.', secret: 'Egy eltűnt halász családjáról tudja, hogy nem hajóbaleset történt. Egy kikötői tiszt tudta, hogy mi történt.', questRole: 'A kikötő hétköznapi, becsületes életének hangja.' },
  harborTessa: { history: 'Tessa több hajót szolgált, és túl sok kapitányt látott felelősség nélkül parancsolni. Egy alkalommal a kapitánya a viharban eladta volna az egyik matróz életét egy gyorsabb útért. Tessa felmondott, bár tudta, hogy ezzel hónapokra elveszti a megélhetését.', motivation: 'A becsületes tengerészéletet akarja életképes útként megőrizni.', secret: 'Egy hajón szolgált, amelynek rakományáról később kiderült, hogy hamis papíron utazott. Tessa akkor még nem tudta, de valaki más nagyon is tudta.', questRole: 'A tengerészeti becsület és a tisztességes lecsúszás útja.' },
  harborSable: { history: 'Sable szabad hajósként járja a parti vizeket, és nem szeret senki zászlaja alatt állni. Egyszer egy királyi flotta megmentette, és cserébe hűséget kértek volna tőle. Sable inkább három napig evezett egyedül, mintsem hogy esküt tegyen.', motivation: 'Független útvonalakat akar építeni a világ felé.', secret: 'Tud egy szigetről, ahol a Fekete Érme nyomai régen is megjelentek. A térképen nincs rajta.', questRole: 'A későbbi világnyitás és új területek kapuja.' },
  harborMira: { history: 'Mira a kikötő sötétebb üzleteiben tanult meg túlélni. Egy hajó fedélzetén nőtt fel, ahol senki sem kérdezte, kitől származik a láda, csak azt, mennyit ér. Egyetlen alkalommal nemet mondott egy rakományra, és látta, hogy a társai közül ketten eltűnnek. Azóta nem hisz az egyszerű döntésekben.', motivation: 'Azt akarja, hogy soha többé ne legyen kiszolgáltatott. A szabadságot nem a törvény hiányának, hanem a menekülés lehetőségének tekinti.', secret: 'Ő már tudja, hogy a Fekete Érme mögött nem egyetlen városi csoport áll. A tengeri hálózat nagyobb, mint amit a Palota most lát.', questRole: 'A kikötői alvilág és a főtörténet legsötétebb összekötője.' },
  marketInn: { history: 'Liora karavánfogadók között nőtt fel, ahol a vendég érkezése mindig egy történet végét és egy másik kezdetét jelentette. Egy elveszett útitársat éveken át várt vissza, ezért a fogadója egyik szabálya az lett, hogy soha senkit nem küld el csak azért, mert nincs pénze. A számlát majd később rendezi az ember — ha marad rá ideje.', motivation: 'Azt akarja, hogy a kereskedők ne csupán pénzt, hanem biztonságot is vásárolhassanak.', secret: 'Egy eltűnt karaván utolsó vendéglistáját ő őrzi. A lista utolsó neve mellett egyetlen fekete pont van.', questRole: 'A Kereskedelmi Központ éjszakai menedéke és informális hírcsomópontja.' },
  marketSmith: { history: 'Garrik egy céhes műhelyből lépett ki, mert nem akart hulladékot hagyni a munkapadján. Egyetlen szétszedett kardból három használható alkatrészt nyert ki, és ekkor döntötte el, hogy a kovács számára a tárgy második élete ugyanolyan fontos, mint az első.', motivation: 'Azt akarja bizonyítani, hogy a rossz tárgyból is lehet jó alapanyag.', secret: 'Tudja, melyik kereskedő hamisította a minőségi jelzéseket.', questRole: 'A kereskedelem, tárgyeredet és újragyártás kapuja.' },
  arenaInn: { history: 'Mara egykor maga is küzdött, majd rájött, hogy a harcosoknak néha ágyra van nagyobb szükségük, mint új fegyverre. Egy sérült bajnokot egyetlen éjszakán át a saját szobájában rejtegetett, és másnap elvesztette a munkáját. Az Arénában maradt, de többé nem hitt abban, hogy a pihenés mellékes.', motivation: 'Azt akarja, hogy a versenyzők ne pusztán gyorsan, hanem hosszú távon is bírják az Arénát.', secret: 'Ismeri azokat a sebeket, amelyeket néhány bajnok minden mérkőzés előtt eltitkol.', questRole: 'Az Aréna regenerációs és éjszakai életének központja.' },
  arenaSmith: { history: 'Darek katonai kovács családból jött, ahol a fegyver elsődleges feladata az volt, hogy túléljen egy csatát. Az Arénában megtanulta, hogy a fegyver egyben látvány, jel és státusz is. Azóta minden pengében két történetet keres: mire készült, és mire használják.', motivation: 'Azt akarja, hogy a harcos fegyvere ne legyen gyengébb, mint az akarata.', secret: 'Egy régi szállítmányból hiányzik az az anyag, amelyből a bajnoki fegyverek egy része készült.', questRole: 'A harci szettek és arénai felszerelés mechanikai kapuja.' },
  innerSmith: { history: 'Lucan generációk óta elit megrendelőknek dolgozik, de mindig saját pecséttel hagyja el a műhelyét. Egykor egyszerű kovácsként kezdte, de az első művészi kardja után egy nemesi ház felajánlotta, hogy magával viszi. Lucan nemet mondott: azt akarta, hogy a tárgyak őt kövessék, ne ő a megrendelőt.', motivation: 'A ritka felszerelésből műalkotást akar csinálni.', secret: 'Egy politikai család régi fegyverét tartja a műhelye mélyén.', questRole: 'A Belváros és későbbi presztízs-felszerelések mestere.' },
  palaceInn: { history: 'Helena a királyi vendégházban tanulta meg, hogy az udvarban a csend is szolgáltatás. Gyerekként a felső emeletről hallotta a politikai vitákat, de a nevek sosem érdekeltek annyira, mint az, mikor csöndesedett el mindenki egyszerre.', motivation: 'Azt akarja, hogy a jogosan érkezők biztonságban maradhassanak az intrikák között.', secret: 'Több politikai egyezség kezdődött a vendégház étkezőasztalánál, mint a hivatalos termekben.', questRole: 'A Palota diszkrét pihenője és informális találkozóhelye.' },
  palaceSmith: { history: 'Aldren apja is királyi fegyverkovács volt, de ő a díszes fegyverek helyett a használhatóságot választotta. Egy régi királyi páncélt egyszer saját kezűleg javított meg a császári díszterem előtt, mert nem akarta, hogy a tulajdonosa egy díszes, de törékeny vértben menjen háborúba.', motivation: 'Azt akarja, hogy a korona fegyverei valódi harcra is alkalmasak legyenek.', secret: 'Egy régi királyi páncélban olyan anyagot talált, amely nem innen származik.', questRole: 'A Palota elit felszerelésének és régi anyagainak őrzője.' },
  harborInn: { history: 'Nera évekig egy hajókonyhán dolgozott, majd rájött, hogy a kikötőben az embereknek ugyanúgy kell menedék, mint a hajóknak kikötő. Egy viharos éjszakán húsz tengerészt engedett be ingyen, és reggelre az egész fogadót víz állta. Mégis azt mondta: megérte.', motivation: 'Azt akarja, hogy a tengerre készülők tiszta fejjel, éhesen ne induljanak.', secret: 'Egy régi kapitány nála hagyott egy lezárt ládát, amelyért soha nem jött vissza.', questRole: 'A Kikötő pihenésének, étkezésének és éjszakai menedékének kapuja.' },
  harborSmith: { history: 'Brann a hajóácsok és kikötői kovácsok között nőtt fel, ahol a rozsdát gyorsan kellett legyőzni. Egyszer egy viharban egy apró csavar törése miatt majdnem elsüllyedt egy hajó; azóta minden apró alkatrészre úgy néz, mintha az egész legénység élete azon függne.', motivation: 'Olyan felszerelést akar adni a tengerészeknek, ami túléli a következő vihart is.', secret: 'Egy eltűnt hajó horgonyán ugyanazt a fekete jelet látta, mint a városban.', questRole: 'A Kikötő harci, ügyességi és tengerészeti felszereléseinek mestere.' },
};

