function buildMainQuest(id:string,title:string,region:any,giver:any,summary:string,story:string,objective:string,chapter:number,sequence:number,requires?:string,consequence?:string): QuestDefinition {
  const gate = MAIN_REGION_ENTRY[region] ?? { reputation: 0, cost: 0 }; const first = sequence===1; const stats = MAIN_CHOICE_STATS[region]; const labels = MAIN_CHOICE_SETS[region];
  const base = 24 + chapter*5 + sequence*2;
  const mk=(i:number): QuestChoice=>({ id:`${id}_c${i+1}`, label:labels[i], text: i===0 ? "A bizonyítékot választod, és a következő lépésednek nyoma marad." : i===1 ? "Egy emberi kapcsolatból csinálsz erőforrást, és más hangot kapsz vissza." : "Kockázatosabb utat választasz; lehet gyorsabb, de a következménye is messzebbre ér.", stat: stats[i] as any, requirement: 5 + Math.floor(sequence/5) + (chapter>3?1:0), gold: base + i*6, xp: base + 6 + i*3, reputation: {achievements:4+chapter, decisions:3+i, relationships:2+i, economic:chapter>=3?3:1, growth:1+Math.floor(sequence/6)}, relation:{npc:giver, amount:6+i} });
  return { id,title,region,giver,summary,story,objective,kind:"main",chapter,sequence,requires,minReputation:first?gate.reputation:0,entryCost:first?gate.cost:0,choices:[mk(0),mk(1),mk(2)],nextQuest: undefined,consequence };
}

export const QUESTS: QuestDefinition[] = [
  buildMainQuest('main_outskirts_01', 'A város első neve', 'outskirts', 'miri', 'Miri nem térképet ad, hanem három nevet: egy kapuőrt, egy raktárőrt és egy férfit, akiről senki sem beszél egyformán.', 'A Külvárosban először meg kell tanulnod, hogy az igazság nem egy helyen lakik.', 'Derítsd ki, ki mozgatja az eltűnt adóládák körüli pletykákat.', 1, 1, undefined, 'A történet innen nem választ utat helyetted; te döntöd el, hogy névhez, pénzhez vagy bizonyítékhoz nyúlsz előbb.'),
  buildMainQuest('main_outskirts_02', 'Pecsét a jelentőteremben', 'outskirts', 'rovan', 'Rovan egy hivatalos ügyet nyit meg előtted: két láda hiányzik, de a papír szerint sosem léteztek.', 'A rendőrség gépezete először érinti a játékos történetét.', 'Azonosítsd a letört fekete viaszpecsét eredetét a városi nyilvántartásban.', 1, 2, 'main_outskirts_01', 'A nyomozás hivatalossá válik, de ezzel valaki odafent is észrevehet.'),
  buildMainQuest('main_outskirts_03', 'A kulcsok számtana', 'outskirts', 'damar', 'Damar tudja, hogy egyetlen kulcs sem tűnik el ok nélkül. A kérdés csak az, ki fizette meg az árát.', 'A raktárakban a Fekete Érme először árumozgásként jelenik meg.', 'Találd meg, melyik raktárkulcs hiányzik és ki használhatta utoljára.', 1, 3, 'main_outskirts_02', 'A nyomok a Régi Piachoz vezetnek, de Damar bizalma attól függ, hogyan szerezted meg az információt.'),
  buildMainQuest('main_outskirts_04', 'Húsz vas', 'outskirts', 'garran', 'Borin új pengét és páncélt készítene, de a műhely készlete megcsappant. Tudod, kitől lehetne megvenni — és kitől lehetne elvenni.', 'A világ most először kéri, hogy ugyanazt a célt többféle erkölcsi úton oldd meg.', 'Szerezz 20 egység vasat Borin számára anélkül, hogy közben elveszítenéd a hírneved.', 1, 4, 'main_outskirts_03', 'Borin mindenképp emlékezni fog a vasra. A forrására is.'),
  buildMainQuest('main_outskirts_05', 'A tinta alja', 'outskirts', 'eldra', 'Eldra szerint a tinta nem városi eredetű. Egy apró szemcsét neked ad, hogy te dönthesd el, mennyit hiszel el.', 'A Fekete Érme anyaga nem egyszerű pénztechnikai ügynek tűnik.', 'Vizsgáld meg a fekete pecsét tintáját és keresd meg a benne lévő idegen port.', 1, 5, 'main_outskirts_04', 'A furcsa por később a kikötői nyomozás egyik kulcsa lesz.'),
  buildMainQuest('main_outskirts_06', 'A túlélő vért', 'outskirts', 'velka', 'Velka szerint valaki rossz anyagot ad el a városnak. A hiba láthatatlan, amíg túl késő nem lesz.', 'A hamisítás most már nem csak pénzt érint.', 'Derítsd ki, miért érkeznek ugyanazzal az új repedéssel a külvárosi őrpáncélok.', 1, 6, 'main_outskirts_05', 'A választásod meghatározza, hogy a műhelyek, az őrség vagy a piac felé erősödik a kapcsolatod.'),
  buildMainQuest('main_outskirts_07', 'A fogadó hallgatása', 'outskirts', 'alma', 'Alma nem kérdezett, amikor a férfi bejött. De emlékszik arra, mit rendelt, ki ült mellette és mikor indult el.', 'A világ története a fogadókban is él.', 'Szerezd meg egy eltűnt karavános utolsó esti beszélgetésének három részletét.', 1, 7, 'main_outskirts_06', 'A részletek egy útvonalat rajzolnak ki a karavánudvar felé.'),
  buildMainQuest('main_outskirts_08', 'A rossz kanyar', 'outskirts', 'petar', 'Petar lovai nem hazudnak: egy helyen letértek az útról, mielőtt visszatértek volna.', 'A szállítmány története a városfalon túlra is kinyúlik.', 'Kövesd vissza azt az útvonalat, amelyen a ládák elvesztek.', 1, 8, 'main_outskirts_07', 'Az utazás mikéntje megmutatja, hogy a játékos inkább túlél, alkudozik vagy kockáztat.'),
  buildMainQuest('main_outskirts_09', 'Királyarca, hamis súly', 'outskirts', 'vera', 'Vera nem bízik a király arcában. A mérlegben igen. Egy érme egy hajszálnyival könnyebb.', 'A hamis pénz végre fizikai bizonyítékká válik.', 'Vizsgálj meg három különböző címletű érmét, és találd meg az eltérő súlyút.', 1, 9, 'main_outskirts_08', 'A hamis érme eredete a Régi Piacra mutat.'),
  buildMainQuest('main_outskirts_10', 'A térkép fehér foltja', 'outskirts', 'jarek', 'Jarek több utat ismer, mint amennyit a város hivatalosan nyilvántart. Az egyik most hiányzik a térképről.', 'A város geometriája maga is nyomokat rejt.', 'Találd meg a térkép azon útját, amelyet valaki szándékosan kiradírozott.', 1, 10, 'main_outskirts_09', 'A játékos először találkozik azzal, hogy valaki nem csak pénzt, hanem utat is rejteget.'),
  buildMainQuest('main_outskirts_11', 'A bőr, ami nem városból jött', 'outskirts', 'nara', 'Nara felismer egy különleges sózási eljárást. Ugyanezt látott egy idegen kereskedő áruján.', 'A Külváros lassan összekapcsolódik a nagy kereskedelmi hálózattal.', 'Azonosítsd annak a bőrnek az eredetét, amelyből több gyanús szállítmány készült.', 1, 11, 'main_outskirts_10', 'A nyom a Kereskedelmi Központba vezet, de Nara csak neked mondja el.'),
  buildMainQuest('main_outskirts_12', 'A mester első hibája', 'outskirts', 'tomen', 'Tomen véletlenül talált valamit, amit mesterei nem akarnak látni.', 'A fiatal tanonc története rámutat, hogy a Fekete Érme nem mai összeesküvés.', 'Javíts meg egy olyan szerszámot, amelyen ugyanaz a furcsa jel látható, mint a fekete pecséten.', 1, 12, 'main_outskirts_11', 'A játékos eldöntheti, védi-e Toment vagy felhasználja a tudását.'),
  buildMainQuest('main_outskirts_13', 'Fűszer az ismeretlen hajóról', 'outskirts', 'zora', 'Zora az illatból felismeri a kikötői eredetet. A kérdés: miért került a Külvárosba?', 'Az első tiszta hivatkozás a tenger felé mutat.', 'Találd meg, melyik hajó hozta azt a fűszert, amely csak egyetlen rakományban jelent meg.', 1, 13, 'main_outskirts_12', 'A nyom egy későbbi kikötői szál alapja lesz.'),
  buildMainQuest('main_outskirts_14', 'A számok nem stimmelnek', 'outskirts', 'cador', 'Cador szerint a hamisítás tökéletesnek tűnik, amíg nem veted össze a megfelelő három időpontot.', 'A számok mögött lassan látszik egy rendszer.', 'Egyeztesd össze három könyvelő három eltérő készletadatát.', 1, 14, 'main_outskirts_13', 'A helyes számítás megnyitja a piac felé vezető főszálat.'),
  buildMainQuest('main_outskirts_15', 'A piaci fül', 'outskirts', 'pell', 'Pell három változatát hallotta ugyanannak a történetnek. A közös rész az érdekes.', 'A pletyka már régen megelőzte a hivatalos jelentéseket.', 'Szerezd meg egyetlen reggeli piacról azt a pletykát, amely mindenkihez máshogy jutott el.', 1, 15, 'main_outskirts_14', 'A játékos megtanulja, hogy az információ minősége ugyanolyan fontos, mint a mennyisége.'),
  buildMainQuest('main_outskirts_16', 'Egy asztal, három tartozás', 'outskirts', 'havel', 'Havel szerint a kártyások nem ugyanazt veszítik el. Valaki pénzt, valaki arcot, valaki szabadságot.', 'A szerencsejáték világa először érinti a Fekete Érme történetét.', 'Tudd meg, mi köti össze ugyanazon az éjszakán három vesztest a Vörös Utcákon.', 1, 16, 'main_outskirts_15', 'A játékos később az Arénában fogja viszontlátni a fogadásokat.'),
  buildMainQuest('main_outskirts_17', 'Az első fekete szegély', 'outskirts', 'brenka', 'Brenka szerint valaki nem az eredményre fogad, hanem arra, hogy mennyi pénz áramlik egy mérkőzésen.', 'A Fekete Érme belép az Aréna gazdaságába.', 'Vesd össze három arénai oddsot az utolsó mérkőzések eredményeivel.', 1, 17, 'main_outskirts_16', 'A szál természetesen az Arénába vezet.'),
  buildMainQuest('main_outskirts_18', 'A név mögötti ember', 'outskirts', 'silas', 'Silas tudja, hogy egy név kimondása ajtókat nyit — vagy bezár.', 'Az információs hálózat már egy szinttel a piac alatt működik.', 'Találd meg azt a közvetítőt, akit Silas csak egyetlen becenéven mer kimondani.', 1, 18, 'main_outskirts_17', 'A játékos megkapja első valódi kapcsolatát a város rejtett kereskedelméhez.'),
  buildMainQuest('main_outskirts_19', 'A zárt pince', 'outskirts', 'tosk', 'Tosk nem enged át senkit kérdés nélkül. A kulcs nem feltétlenül fémből készül.', 'A küldetés első valódi hozzáférési próbája.', 'Döntsd el, hogyan jutsz be egy zárt pincehelyiségbe, ahol egy könyvnyomot rejtenek.', 1, 19, 'main_outskirts_18', 'A megszerzett könyv alapján az Őrségi Negyed felé lehet lépni.'),
  buildMainQuest('main_outskirts_20', 'A hiányzó pecsét', 'outskirts', 'lena', 'Lena szerint a papírnak emlékezete van. Valaki egyetlen pecséttel átírta az ügy útját.', 'A hivatalos és a fekete gazdaság között most már tárgyi kapcsolat van.', 'Találd meg, melyik okiratból hiányzik ugyanaz a fekete pecsét, mint az első szállítmányról.', 1, 20, 'main_outskirts_19', 'A bizonyítékot átadhatod az őrségnek, vagy megőrizheted a későbbi döntéshez.'),
  buildMainQuest('main_outskirts_21', 'A csendes fogda', 'outskirts', 'bran', 'Bran egy éjszakai kiengedés nyomára talált, de a nyilvántartás üres.', 'A nagy ügy mögött először jelenik meg valaki, aki élő emberként része a láncnak.', 'Derítsd ki, kit engedtek ki úgy, hogy reggel nem maradt róla hivatalos bejegyzés.', 1, 21, 'main_outskirts_20', 'A játékos eldönti, hogy a nevet védi vagy felhasználja.'),
  buildMainQuest('main_outskirts_22', 'A hatperces rés', 'outskirts', 'orren', 'Orren hatperces rést talált minden éjszakai őrségi körben.', 'A város órája most már a történet része: valaki az időt használja fel.', 'Kövesd végig egy teljes őrségi ciklus útvonalát, és találd meg a szabályos rendszert megtörő pontot.', 1, 22, 'main_outskirts_21', 'A nyom egy későbbi raktári találkozás időpontját rögzíti.'),
  buildMainQuest('main_outskirts_23', 'A kő, ami emlékszik', 'outskirts', 'siven', 'Siven egy régi kőlapot talált, amely ugyanazt a geometriai jelet viseli, mint Eldra tintája.', 'A Fekete Érme története hirtelen régebbinek tűnik, mint a jelenlegi pénzverés.', 'Fejtsd meg a Régi Perem jelének eredeti jelentését.', 1, 23, 'main_outskirts_22', 'A jel értelme később a Palota archívumában kap megerősítést.'),
  buildMainQuest('main_outskirts_24', 'A néma kút alatt', 'outskirts', 'maela', 'Maela szerint a kút alatt üres hely van, amelyet a város régen elfelejtett.', 'A Külváros mélyén valami régebbi világ kezd kirajzolódni.', 'Találd meg, miért változott meg a kút hangja ugyanazon a napon, amikor a láda eltűnt.', 1, 24, 'main_outskirts_23', 'A Külváros fejezete lezárul: a nyomokból összeáll egy út a város többi régiója felé.'),
  buildMainQuest('main_arena_01', 'A belépő ára', 'arena', 'arenaSena', 'Sena szerint az Aréna nem a győzelemmel kezdődik, hanem azzal, hogy elfogadod a szabályokat.', 'A játékos hivatalosan is belép az Aréna társadalmába.', 'Teljesítsd Sena próbaküzdelmét úgy, hogy közben ne veszítsd el a kontrollt.', 2, 1, undefined, 'A teljesítményed alapozza meg a későbbi kihívásokat.'),
  buildMainQuest('main_arena_02', 'A vas és a hús', 'arena', 'arenaKorr', 'Korr egy repedt markolatot ad át. A fegyver nem rossz — csak valaki annak szánta.', 'A manipuláció most a harcosok felszerelésén keresztül támad.', 'Derítsd ki, ki használ szándékosan hibásan kiegyensúlyozott fegyvereket.', 2, 2, 'main_arena_01', 'A nyom a fogadóirodákhoz közelebb visz.'),
  buildMainQuest('main_arena_03', 'A gyógyító titkos listája', 'arena', 'arenaVeya', 'Veya tudja, mely sérülések ismétlődnek túl gyakran egy bizonyos mérkőzéstípus után.', 'A verseny tisztasága orvosi bizonyítékokon is múlik.', 'Szerezz meg egy sérült harcosokról vezetett tiltott jegyzéket.', 2, 3, 'main_arena_02', 'A játékos dönthet, védelmezi-e a sérülteket vagy a bizonyítékot használja fel.'),
  buildMainQuest('main_arena_04', 'Egy név az eredménytáblán', 'arena', 'arenaBram', 'Bram szerint valaki előbb ír történetet, mint hogy megtörténne.', 'A hírnév és a pénz összekapcsolódik.', 'Derítsd ki, miért került fel egy ismeretlen név a fogadólistára a mérkőzés előtt.', 2, 4, 'main_arena_03', 'A játékos először sejti, hogy a nézők között is működik egy szervezett hálózat.'),
  buildMainQuest('main_arena_05', 'Az odds mögötti kéz', 'arena', 'arenaRusk', 'Rusk csak a számokat hajlandó megmutatni. A különbség mégis ordít.', 'A fekete pénz most konkrét útvonalat kap az Aréna könyveiben.', 'Hasonlítsd össze három bukméker oddsait, és találd meg a közös eltérést.', 2, 5, 'main_arena_04', 'A következő nyom a Kereskedelmi Központba vezet.'),
  buildMainQuest('main_arena_06', 'A bajnoki kihívás', 'arena', 'arenaTalia', 'Talia nem a legerősebbeket emeli fel. Azokat, akik vállalják a következményt.', 'A rang és a történet összekapcsolódik.', 'Szerezz jogot egy magasabb rangú ellenfél kihívására, majd döntsd el, mikor használod fel.', 2, 6, 'main_arena_05', 'A játékos hírneve a későbbi társadalmi útjain is érezhető lesz.'),
  buildMainQuest('main_arena_07', 'A fegyvertár pecsétje', 'arena', 'arenaOlen', 'Olen a fémből is felismeri, ha valaki nem az Aréna kedvéért gyárt.', 'A beszállítói hálózat ugyanarra az útvonalra mutat, mint a fekete pénz.', 'Azonosítsd, mely fegyverek kerültek be külső beszállítótól az utolsó hónapban.', 2, 7, 'main_arena_06', 'A Kereskedelmi Központ felé nyílik a bizonyíték.'),
  buildMainQuest('main_arena_08', 'A győzelem, amit nem adtak el', 'arena', 'serin', 'Serin nem akar bajnokot csinálni belőled. Azt akarja tudni, képes vagy-e nemet mondani a könnyű győzelemre.', 'A Fekete Érme első teljes pénzügyi nyoma összeáll.', 'Szerezd meg az Aréna alatti könyvet, amely a megrendezett mérkőzések pénzmozgását rögzíti.', 2, 8, 'main_arena_07', 'Az ügy innentől már túl nagy ahhoz, hogy csak az Arénában maradjon.'),
  buildMainQuest('main_market_01', 'A fekete tinta ára', 'market', 'ilren', 'Ilren könyvei már nem egyszerű üzleti iratok. Olyanok, mint egy második várostérkép.', 'A kereskedői hálózat rákapcsolódik az Aréna pénzére.', 'Térképezd fel három gyanús raktári tranzakció közös mintáját.', 3, 1, undefined, 'A bizonyíték a raktárgyűrű felé húz.'),
  buildMainQuest('main_market_02', 'Karaván, amely nem érkezett meg', 'market', 'malk', 'Malk szerint egy karaván nem tűnik el — valaki egyszerűen átírja, merre ment.', 'A Fekete Érme mögött logisztikai rendszer körvonalazódik.', 'Találd meg a hibás karavánjegyet és követd a rakomány útját.', 3, 2, 'main_market_01', 'A Kikötő felé vezető útvonal először kerül a főtörténetbe.'),
  buildMainQuest('main_market_03', 'A céh ára', 'market', 'sera', 'Sera hivatalos úton vagy személyes szívesség árán tudja megnyitni ugyanazt az ajtót.', 'A pénz önmagában már kevés: kapcsolat kell.', 'Döntsd el, hogyan szerezz hozzáférést egy zárt céhes nyilvántartáshoz.', 3, 3, 'main_market_02', 'A játékos első ízben kerül olyan helyzetbe, ahol a hírnév felülírja az aranyat.'),
  buildMainQuest('main_market_04', 'A készlet, ami sosem hiányzik', 'market', 'oris', 'Oris minden hiányzó ládához talál egy látszólag érvényes magyarázatot.', 'A rendszer nem hibás. Valaki pontosan így tervezte.', 'Egyeztesd össze a raktárak fizikai és papírkészletét.', 3, 4, 'main_market_03', 'A főkönyvi csalás összekapcsolható a kikötői rakjegyekkel.'),
  buildMainQuest('main_market_05', 'A ritka áru eredete', 'market', 'niven', 'Niven üzletei olyan árukhoz kapcsolódnak, amelyeknek nem kellene itt lenniük.', 'A főváros és a tenger közötti forgalom sötét oldala kirajzolódik.', 'Azonosítsd egy ritka tárgy tényleges származási útvonalát.', 3, 5, 'main_market_04', 'Niven akkor is ad információt, ha nem vásárolsz — de csak megfelelő megközelítéssel.'),
  buildMainQuest('main_market_06', 'Az alku, ami túl könnyű', 'market', 'taris', 'Taris szerint az a jó üzlet, amelyet minden fél másképp értelmez.', 'A Fekete Érme több ember hasznát is szolgálhatja egyszerre.', 'Bontsd fel egy gyanúsan kedvező szerződés rejtett feltételeit.', 3, 6, 'main_market_05', 'A nyom a Belváros hitelügyei felé vezet.'),
  buildMainQuest('main_market_07', 'A tartozás könyve', 'market', 'cassian', 'Cassian semmit sem ad ingyen — de a számoknak is ára van.', 'A fekete pénz most már adóssággá változik.', 'Találd meg azt az adósságot, amely ugyanahhoz a fekete tranzakcióhoz kapcsolódik, mint az Aréna.', 3, 7, 'main_market_06', 'A Belváros egyik első kapuja megnyílik.'),
  buildMainQuest('main_market_08', 'Az érme, amely máshol könnyebb', 'market', 'lyra', 'Lyra szerint valaki nem csak hamisít. A valódi érméket is áthelyezi.', 'A pénz áramlása célzottabb, mint hittük.', 'Vess össze ugyanabból az érméből három városi készletet.', 3, 8, 'main_market_07', 'A hajós útvonalak szükséges részt kapnak a történetben.'),
  buildMainQuest('main_market_09', 'A biztos út hazugsága', 'market', 'fen', 'Fen tudja, hogy az olcsó út mögött általában valaki más kockázata áll.', 'A kereskedelmi hálózat a kikötői korridorig ér.', 'Találd meg, miért lett ugyanaz az útvonal hirtelen túl olcsó.', 3, 9, 'main_market_08', 'A játékos előtt megjelenik a döntés: több profit vagy kevesebb veszély.'),
  buildMainQuest('main_market_10', 'Hetedik kapu', 'market', 'marwen', 'Marwen egyetlen hibát talált a pecséten. Neked kell bizonyítani, hogy nem véletlen.', 'Az ügy innentől politikai szintre emelhető.', 'Vizsgáld meg a zárolt raktár pecsétjét, és bizonyítsd be, mikor nyitották ki valójában.', 3, 10, 'main_market_09', 'A Palota iratai felé vezető kapu megnyílik.'),
  buildMainQuest('main_inner_01', 'A meghívó neve', 'inner', 'adrian', 'Adrian szerint a Belvárosban a megfelelő név többet ér, mint egy teljes pénztárca.', 'A játékos belép a társadalmi hatalom világába.', 'Szerezz meghívást egy olyan estére, ahová a Kereskedelmi Központ pénze önmagában nem elég.', 4, 1, undefined, 'A kapcsolatod értéke láthatóbbá válik, mint a vagyonod.'),
  buildMainQuest('main_inner_02', 'A vendéglista másik fele', 'inner', 'selene', 'Selene vendéglistája a város egyik legtisztább politikai térképe.', 'A történet megmutatja, hogy a hiányzó ember is adat.', 'Derítsd ki, ki került ki a szalon vendéglistájáról az utolsó pillanatban.', 4, 2, 'main_inner_01', 'A nyom a zárt klubok felé vezet.'),
  buildMainQuest('main_inner_03', 'A játék, amelyet nem lehet megnyerni', 'inner', 'marcell', 'Marcell egy olyan játékra hív, ahol az arany mellett ígéretet is lehet tenni.', 'A szerencsejáték most már politikai információt mozgat.', 'Tedd próbára egy zárt asztal szabályait úgy, hogy közben ne veszítsd el a saját mozgástered.', 4, 3, 'main_inner_02', 'A játékos dönthet gyors pénz, információ vagy önfegyelem között.'),
  buildMainQuest('main_inner_04', 'A kölcsön ára', 'inner', 'livia', 'Livia szerint minden hitel mögött van fedezet. A kérdés, hogy ki a valódi fedezet.', 'A Fekete Érme története már személyes vagyonokat is érint.', 'Vizsgáld meg, melyik Belvárosi adósság kapcsolódik a kikötői rakományokhoz.', 4, 4, 'main_inner_03', 'A Palota vizsgálata számára fontos nyom keletkezik.'),
  buildMainQuest('main_inner_05', 'A mecénás ajánlata', 'inner', 'octavia', 'Octavia gyűjteményében van egy darab, amelyről senki sem tudja, hogyan került a városba.', 'A kultúra mögött is pénz és politika mozog.', 'Válassz, hogy egy műtárgyat, egy nevet vagy egy titkot ajánlasz fel Octaviának egy kulcsért.', 4, 5, 'main_inner_04', 'A ritka tárgy eredete a Palota archívumába vezet.'),
  buildMainQuest('main_inner_06', 'A fekete lámpás szobája', 'inner', 'corvin', 'Corvin tudja, melyik mondatot kell félrehallani ahhoz, hogy valaki önként eláruljon valamit.', 'A politikai háló láthatatlan oldala kerül elő.', 'Juss be egy zárt klub olyan szobájába, ahol a fontos emberek már nem őrzik a modorukat.', 4, 6, 'main_inner_05', 'A játékos választása meghatározza, hogy bizalmat vagy félelmet épít.'),
  buildMainQuest('main_inner_07', 'A szoba, ahol várnak', 'inner', 'violet', 'Violet diszkréciója miatt a tárgy létezése önmagában is veszélyes.', 'A főváros elitje tud valamit, amit még nem akar a Palotába vinni.', 'Találd meg a vendégszobában hagyott csomagot, amelynek címzettje nem érkezett meg.', 4, 7, 'main_inner_06', 'A történet egyértelműen a Korona felé fordul.'),
  buildMainQuest('main_palace_01', 'Az első audienciakérés', 'palace', 'palaceElian', 'Elian nem azt nézi, igazad van-e. Azt, hogy érdemes-e egyáltalán foglalkozni veled.', 'A játékos először lép be a döntéshozatal központjába.', 'Szerezz lehetőséget arra, hogy a Fekete Érméről hivatalos meghallgatás induljon.', 5, 1, undefined, 'A Palota elfogadja, hogy van ügy — de nem ígéri, hogy hisz neked.'),
  buildMainQuest('main_palace_02', 'A diplomata kérdése', 'palace', 'palaceMara', 'Mara a konfliktust nem nevekkel, hanem érdekekkel írja le.', 'Kiderül, hogy a Fekete Érme útja nem kizárólag belföldi.', 'Derítsd ki, melyik kereskedelmi útvonalat figyeli egyszerre két idegen küldöttség.', 5, 2, 'main_palace_01', 'A Kikötő szerepe történetileg megkerülhetetlenné válik.'),
  buildMainQuest('main_palace_03', 'A pecsétarchívum', 'palace', 'palaceOrven', 'Orven évek óta gyűjti az eltérő intézményi jeleket. Most először ugyanarra a mintára mutatnak.', 'A Fekete Érme nem csak jelenlegi bűnügy. Régebbi történet is lehet.', 'Illeszd össze három régi királyi pecsét történetét az új fekete lenyomattal.', 5, 3, 'main_palace_02', 'A nyomozás hivatalos bizonyítékká válik.'),
  buildMainQuest('main_palace_04', 'A kapuőrök esküje', 'palace', 'palaceAster', 'Aster szerint a Palota legbiztonságosabb ajtói nem a legerősebbek, hanem a legjobban indokoltak.', 'A játékos a rend oldaláról ismeri meg a hatalom természetét.', 'Döntsd el, milyen áron kérsz hozzáférést egy lezárt udvari szárnyhoz.', 5, 4, 'main_palace_03', 'A hozzáférés a Kikötővel kapcsolatos iratokhoz vezet.'),
  buildMainQuest('main_palace_05', 'A könyv, amely nem létezik', 'palace', 'palaceYsra', 'Ysra pontosan tudja, melyik polcon lenne a könyv — és azt is, hogy valaki kivette.', 'A fő történet egy régi, eltemetett összefüggést kap.', 'Találd meg egy eltűnt krónikakötet nyomát az archívum hiányos leltárában.', 5, 5, 'main_palace_04', 'A kikötői hajónevek és a királyi pecsétek közös történetre utalnak.'),
  buildMainQuest('main_harbor_01', 'A rakparti jel', 'harbor', 'harborKael', 'Kael nem szereti a találgatást. Rakjegyet, súlyt és érkezési időt akar.', 'A fő történet a szárazföldről végleg a tengerre költözik.', 'Azonosítsd a hajót, amelynek rakjegye ugyanazt a fekete jelet viseli, mint a Palota iratai.', 6, 1, undefined, 'A nyom egy lezárt raktárhoz vezet.'),
  buildMainQuest('main_harbor_02', 'A rakjegyek sorrendje', 'harbor', 'harborDain', 'Dain szerint a papírok sorrendje hazudik, ha az ember tudja, mikor futott be a hajó.', 'A fekete pénz mozgását hajóútvonalakban lehet olvasni.', 'Állítsd helyre három hajó rakjegyének valódi időrendi sorrendjét.', 6, 2, 'main_harbor_01', 'A főszál innentől nem csak városi ügy.'),
  buildMainQuest('main_harbor_03', 'A só és a fém', 'harbor', 'harborJoren', 'Joren minden kikötői illatot ismer. Egyetlen fémes szag elég neki a felismeréshez.', 'Az egyszerű emberek is hordozzák a nagy történet darabjait.', 'Találd meg a halpiacon azt az árut, amelynek eredete nem lehetne itt.', 6, 3, 'main_harbor_02', 'A játékos megtanulja, hogy a tenger nem csak bűn, hanem közösség.'),
  buildMainQuest('main_harbor_04', 'A becsület hajója', 'harbor', 'harborTessa', 'Tessa lehetőséget ad arra, hogy veszteség után is becsülettel újrakezdj.', 'A Kikötő egyik alapvető életútja megszületik.', 'Döntsd el, hogy egy nehéz, de törvényes hajózási munkát vállalsz-e egy gyorsabb, kétes út helyett.', 6, 4, 'main_harbor_03', 'A választásod a későbbi tengerész- vagy kalózkapcsolataid alapja.'),
  buildMainQuest('main_harbor_05', 'A szabad hajó ajánlata', 'harbor', 'harborSable', 'Sable szerint a Szabad Kikötőben nincs királyi parancs, csak következmény.', 'Az első valódi külső világ felé vezető út megjelenik.', 'Válassz egy útvonalat egy független hajóval, amely túl közel jár a fekete pénzhez.', 6, 5, 'main_harbor_04', 'A játékos számára jövőbeli új városok és világok alapjai nyílnak meg.'),
  buildMainQuest('main_harbor_06', 'A fekete rakomány', 'harbor', 'harborMira', 'Mira nem kérdezi, hogy jó ember vagy-e. Azt kérdezi, hogy kibírod-e a választ.', 'A Fekete Érme most először teljes tárgyi lánccá áll össze.', 'Derítsd ki, mi van egy ládában, amelyet senki sem akar hivatalosan átvállalni.', 6, 6, 'main_harbor_05', 'A következő fejezet már nem a városról, hanem a világ mélyebb hálózatáról szól.'),
];

for (let i=0;i<QUESTS.length;i++){ if(i+1<QUESTS.length && QUESTS[i+1].region===QUESTS[i].region) QUESTS[i].nextQuest=QUESTS[i+1].id; }
for (const quest of QUESTS) {
  quest.audit = MAIN_QUEST_AUDIT[quest.id];
  const design = designQuest(quest);
  quest.requirements = design.requirements;
  quest.dramaturgy = design.dramaturgy;
  quest.choices = design.choices;
  if (quest.id !== "main_outskirts_04" && !quest.requirements?.length) {
    // All later quests receive a tangible narrative objective. Some require clues/items, others use their NPC function or a stat threshold.
    const pools: Record<string,string[]> = {
      outskirts:["gateRations","saltFish","workshopIron","tannersWax","streetMap","redStreetTokens","watchSeal","sealedLetter"],
      arena:["arenaBandages","gladiatorOil","arenaWhetstone","crowdScrip","matchLedger","arenaBlackToken","arenaProtein","arenaResin"],
      market:["tradeSilk","merchantInk","sealedLedger","caravanCompass","guildPermit","warehouseSeal","blackCoinLedgerFragment","guildMeal","caravanToolKit"],
      inner:["velvetWine","casinoChips","silkGloves","promissoryNote","patronInvitation","luxuryCigar","debtMarker","innerBanquet"],
      palace:["royalSealWax","courtInvitation","royalArchiveCopy","courtSealRing","diplomaticToken","sealedTestimony","blackArchiveIndex","royalTransitPass"],
      harbor:["shipRepairKit","sailorsStew","saltFish","sailcloth","sailorsKnife","navigatorChart","smugglersPass","captainsLogPage","blackCoinCargoTag"]
    };
    const pool=pools[quest.region]||pools.outskirts;
    const itemId=pool[(quest.sequence-1)%pool.length];
    const itemDef=ITEMS.find(item=>item.id===itemId);
    const chapterBase = Math.max(1, quest.chapter * 2);
    const count = ["document","quest","key","relic"] .includes(itemDef?.category ?? "") ? 1 : chapterBase + Math.floor(quest.sequence/8);
    quest.requirements=[{label:`${count} × ${itemDef?.name ?? itemId}`,itemId,count,consume: quest.sequence%3===0}];
  }
}

const AUTHORED_QUESTS_V128 = applyMainStory(QUESTS);
QUESTS.splice(0, QUESTS.length, ...AUTHORED_QUESTS_V128);
